head.script:
scwin.trigger1_onclick = function(e) {
    jsonData1 = [{
        "col1": "test1_1",
        "col2": "test1_2"
    }]
    jsonData2 = [{
        "col1": "test2_1",
        "col2": "test2_2"
    }]
    jsonData3 = [{
        "col1": "test3_1",
        "col2": "test3_2"
    }]
    dataList1.setJSON(jsonData1, true);
    dataList1.setJSON(jsonData2, true);
    dataList1.setJSON(jsonData3, true);
};
scwin.trigger2_onclick = function(e) {
    dataList1.removeRow(2);
    dataList1.removeRow(1);
};
scwin.trigger3_onclick = function(e) {
    jsonData4 = [{
        "col1": "test4_1",
        "col2": "test4_2"
    }]
    dataList1.setJSON(jsonData4, true);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 setp1.setJson(jsondata,true) 버튼을 클릭한다.-  
    //In your browser, click the setp1.setJson (jsondata, true) button.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    //Verify 1. 컬럼 데이터 3줄이 생성된다.- 
    //Three lines of column data are generated.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody tr').not('.w2grid_hidedRow').length == 3", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. setp2.removeRow 버튼을 클릭한다.
    //Click the setp2.removeRow button.            
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 컬럼 데이터 2줄이 삭제된다
    //Two lines of column data are deleted
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody tr').not('.w2grid_hidedRow').length == 1", "true");
    //Test step 3. step3.setJson(jsondata,true) 버튼을 클릭한다.
    //Click the step3.setJson (jsondata, true) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify3. 컬럼 데이터 1줄이 생성된다.
    //One line of column data is generated.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody tr').not('.w2grid_hidedRow').length == 2", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
    //Create by Truong.Luu
    //Create date 22-Jan-2018
    //End unitTest
}
